def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    non_bg_counts = Counter(v for row in grid for v in row if v != bg)
    marker = non_bg_counts.most_common(1)[0][0]

    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    eligible = lambda r, c: grid[r][c] != bg and grid[r][c] != marker

    # Find the longest straight contiguous run that forms the pattern.
    best = []
    for r in range(h):
        c = 0
        while c < w:
            if eligible(r, c):
                run = []
                while c < w and eligible(r, c):
                    run.append((r, c))
                    c += 1
                if len(run) > len(best):
                    best = run
            else:
                c += 1
    for c in range(w):
        r = 0
        while r < h:
            if eligible(r, c):
                run = []
                while r < h and eligible(r, c):
                    run.append((r, c))
                    r += 1
                if len(run) > len(best):
                    best = run
            else:
                r += 1

    out = [row[:] for row in grid]
    if not best:
        return out

    vertical = len(best) > 1 and best[0][1] == best[1][1]
    center = len(best) // 2
    pattern = [grid[r][c] for r, c in best]

    for mr, mc in markers:
        for i, color in enumerate(pattern):
            offset = i - center
            r = mr + offset if vertical else mr
            c = mc if vertical else mc + offset
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color

    return out
